insert into public.access_assignments(id,membership_id,customer_id,organizer_id,function)
values ('33000000-0000-4000-8000-000000000998','33000000-0000-4000-8000-000000000031','33000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000011','huvudman');
select is(public.assignment_is_valid(a),true,'befintlig fas 2-giltighet bevaras')
from public.access_assignments a where id='33000000-0000-4000-8000-000000000998';
set local role skolplattform_worker;
select set_config('app.customer_id','33000000-0000-4000-8000-000000000001',true);
select set_config('app.identity_id','33000000-0000-4000-8000-000000000021',true);
select set_config('app.phase','',true);
select throws_ok($test$update public.access_assignments set profile_id=null,scope_kind=null where id='33000000-0000-4000-8000-000000000041'$test$, '42501', null, 'worker får inte omvandla fas 3 till fas 2');
select throws_ok($test$update public.access_assignments set profile_id='synthetic-v1',scope_kind='school' where id='33000000-0000-4000-8000-000000000998'$test$, '42501', null, 'worker får inte omvandla fas 2 till fas 3');
select throws_ok($test$insert into public.access_assignments(membership_id,customer_id,organizer_id,function,profile_id,scope_kind) values ('33000000-0000-4000-8000-000000000031','33000000-0000-4000-8000-000000000001','33000000-0000-4000-8000-000000000011','it','synthetic-v1','school')$test$, '42501', null, 'worker får inte skapa nya mandat före kontrollerad väg');
select throws_ok($test$select * from public.mandate_units$test$, '42501', null, 'faktisk worker nekas mandate_units');
select throws_ok($test$select * from public.mandate_groups$test$, '42501', null, 'faktisk worker nekas mandate_groups');
select throws_ok($test$select * from public.mandate_pupils$test$, '42501', null, 'faktisk worker nekas mandate_pupils');
select throws_ok($test$select * from public.mandate_cases$test$, '42501', null, 'faktisk worker nekas mandate_cases');
select throws_ok($test$select * from public.phase3_probe_pupils$test$, '42501', null, 'faktisk worker nekas phase3_probe_pupils');
select throws_ok($test$select * from public.phase3_probe_groups$test$, '42501', null, 'faktisk worker nekas phase3_probe_groups');
select throws_ok($test$select * from public.phase3_probe_group_members$test$, '42501', null, 'faktisk worker nekas phase3_probe_group_members');
select throws_ok($test$select * from public.phase3_probe_cases$test$, '42501', null, 'faktisk worker nekas phase3_probe_cases');
select throws_ok($test$select * from public.local_connection_configs$test$, '42501', null, 'faktisk worker nekas local_connection_configs');
reset role;
set local role anon;
select throws_ok($test$select * from public.phase3_probe_pupils$test$, '42501', null, 'faktisk anon nekas elevprovet');
reset role;
set local role authenticated;
select throws_ok($test$select * from public.phase3_probe_pupils$test$, '42501', null, 'faktisk authenticated nekas elevprovet');
reset role;
select is((select count(*) from public.access_assignments where id='33000000-0000-4000-8000-000000000041' and profile_id='synthetic-v1'),1::bigint,'nekad ändring lämnar mandatet oförändrat');
select * from finish();
rollback;
